pub fn days_to_next_sunday(day: &str) -> i8 {
    // Map the day to an index where 0 = SUN, 1 = MON, ..., 6 = SAT.
    let idx: i8 = match day {
        "SUN" => 0,
        "MON" => 1,
        "TUE" => 2,
        "WED" => 3,
        "THU" => 4,
        "FRI" => 5,
        "SAT" => 6,
        _ => unreachable!("Input is guaranteed to be a valid day abbreviation"),
    };

    // Distance to next Sunday (not including today). If today is Sunday, return 7.
    let diff = (7 - idx) % 7;
    if diff == 0 { 7 } else { diff }
}

